static const char example_2[] =
    "// Run: vanta /Development/linear_solver.vanta\n"
    "// Gauss-Jordan elimination with partial pivoting solves A*x = b.\n"
    "// Rows below contain the coefficients followed by the right-hand side.\n"
    "let rows = [[2.0, 1.0, -1.0, 8.0], [-3.0, -1.0, 2.0, -11.0], [-2.0, 1.0, 2.0, -3.0]]\n"
    "let n = len(rows)\n"
    "for let col = 0; col < n; col++ {\n"
    "    let pivot = col\n"
    "    for let row = col + 1; row < n; row++ {\n"
    "        if abs(rows[row][col]) > abs(rows[pivot][col]) { pivot = row }\n"
    "    }\n"
    "    assert(abs(rows[pivot][col]) > 0.000001)\n"
    "    let swap = rows[col]\n"
    "    rows[col] = rows[pivot]\n"
    "    rows[pivot] = swap\n"
    "    let divisor = rows[col][col]\n"
    "    for let j = col; j <= n; j++ { rows[col][j] = rows[col][j] / divisor }\n"
    "    for let row = 0; row < n; row++ {\n"
    "        if row != col {\n"
    "            let factor = rows[row][col]\n"
    "            for let j = col; j <= n; j++ {\n"
    "                rows[row][j] = rows[row][j] - factor * rows[col][j]\n"
    "            }\n"
    "        }\n"
    "    }\n"
    "}\n"
    "// This system has an integer solution; round only for display.\n"
    "for let i = 0; i < n; i++ { println(\"x[\", i, \"] = \", int(round(rows[i][n]))) }\n"
    "assert(abs(rows[0][n] - 2.0) < 0.000001)\n"
    "assert(abs(rows[1][n] - 3.0) < 0.000001)\n"
    "assert(abs(rows[2][n] + 1.0) < 0.000001)\n"
;

static const char example_3[] =
    "// Run: vanta /Development/mandelbrot.vanta\n"
    "// Complex numbers are represented by separate real/imaginary parts.\n"
    "let width = 64\n"
    "let height = 22\n"
    "let limit = 40\n"
    "let shades = \" .:-=+*#%@\"\n"
    "for let py = 0; py < height; py++ {\n"
    "    let line = \"\"\n"
    "    for let px = 0; px < width; px++ {\n"
    "        let cr = -2.1 + px * 3.0 / (width - 1)\n"
    "        let ci = -1.1 + py * 2.2 / (height - 1)\n"
    "        let zr = 0.0\n"
    "        let zi = 0.0\n"
    "        let iteration = 0\n"
    "        while zr * zr + zi * zi <= 4.0 && iteration < limit {\n"
    "            let next_real = zr * zr - zi * zi + cr\n"
    "            zi = 2.0 * zr * zi + ci\n"
    "            zr = next_real\n"
    "            iteration++\n"
    "        }\n"
    "        let shade = int(iteration * (len(shades) - 1) / limit)\n"
    "        line += shades[shade]\n"
    "    }\n"
    "    println(line)\n"
    "}\n"
;

static const char example_4[] =
    "// Run: vanta /Development/merge_sort.vanta\n"
    "// A stable recursive merge sort: O(n log n) comparisons.\n"
    "fn merge_sort(values) {\n"
    "    if len(values) <= 1 { return values }\n"
    "    let middle = len(values) / 2\n"
    "    let left = []\n"
    "    let right = []\n"
    "    for let i = 0; i < len(values); i++ {\n"
    "        if i < middle { left.push(values[i]) } else { right.push(values[i]) }\n"
    "    }\n"
    "    left = merge_sort(left)\n"
    "    right = merge_sort(right)\n"
    "    let result = []\n"
    "    let a = 0\n"
    "    let b = 0\n"
    "    while a < len(left) && b < len(right) {\n"
    "        if left[a] <= right[b] { result.push(left[a]); a++ } else { result.push(right[b]); b++ }\n"
    "    }\n"
    "    while a < len(left) { result.push(left[a]); a++ }\n"
    "    while b < len(right) { result.push(right[b]); b++ }\n"
    "    return result\n"
    "}\n"
    "let input = [42, -7, 13, 0, 42, 8, 3, 99, -20, 5, 1]\n"
    "let sorted = merge_sort(input)\n"
    "println(\"Input:  \", input)\n"
    "println(\"Sorted: \", sorted)\n"
    "for let i = 1; i < len(sorted); i++ { assert(sorted[i - 1] <= sorted[i]) }\n"
    "assert(len(sorted) == len(input))\n"
;

static const char example_5[] =
    "// Run: vanta /Development/pathfinding.vanta\n"
    "// Breadth-first search finds a shortest route through a maze.\n"
    "let width = 8\n"
    "let height = 6\n"
    "let maze = [\n"
    "    \"........\",\n"
    "    \".#####..\",\n"
    "    \".....#..\",\n"
    "    \".###.#..\",\n"
    "    \"...#....\",\n"
    "    \"........\"\n"
    "]\n"
    "let previous = []\n"
    "for let i = 0; i < width * height; i++ { previous.push(-1) }\n"
    "let queue = [0]\n"
    "let head = 0\n"
    "previous[0] = 0\n"
    "let goal = width * height - 1\n"
    "let dx = [1, 0, -1, 0]\n"
    "let dy = [0, 1, 0, -1]\n"
    "while head < len(queue) && previous[goal] == -1 {\n"
    "    let cell = queue[head]\n"
    "    head++\n"
    "    let x = cell % width\n"
    "    let y = int(cell / width)\n"
    "    for let direction = 0; direction < 4; direction++ {\n"
    "        let nx = x + dx[direction]\n"
    "        let ny = y + dy[direction]\n"
    "        if nx >= 0 && nx < width && ny >= 0 && ny < height {\n"
    "            let next = ny * width + nx\n"
    "            if maze[ny][nx] != \"#\" && previous[next] == -1 {\n"
    "                previous[next] = cell\n"
    "                queue.push(next)\n"
    "            }\n"
    "        }\n"
    "    }\n"
    "}\n"
    "assert(previous[goal] != -1)\n"
    "let route = []\n"
    "let current = goal\n"
    "while current != 0 { route.push(current); current = previous[current] }\n"
    "route.push(0)\n"
    "println(\"Shortest route takes \", len(route) - 1, \" steps:\")\n"
    "for let i = len(route) - 1; i >= 0; i-- {\n"
    "    println(\"(\", route[i] % width, \", \", int(route[i] / width), \")\")\n"
    "}\n"
    "assert(len(route) - 1 == 12)\n"
;

static const char example_6[] =
    "// Run: vanta /Development/scheduler.vanta\n"
    "// Simulate round-robin CPU scheduling and measure waiting time.\n"
    "let names = [\"editor\", \"audio\", \"compile\", \"network\"]\n"
    "let burst = [7, 3, 11, 5]\n"
    "let remaining = [7, 3, 11, 5]\n"
    "let completed = [0, 0, 0, 0]\n"
    "let quantum = 2\n"
    "let clock = 0\n"
    "let finished = 0\n"
    "while finished < len(names) {\n"
    "    for let job = 0; job < len(names); job++ {\n"
    "        if remaining[job] > 0 {\n"
    "            let slice = min(quantum, remaining[job])\n"
    "            println(\"t=\", clock, \" run \", names[job], \" for \", slice)\n"
    "            clock += slice\n"
    "            remaining[job] -= slice\n"
    "            if remaining[job] == 0 { completed[job] = clock; finished++ }\n"
    "        }\n"
    "    }\n"
    "}\n"
    "let waiting = 0\n"
    "for let job = 0; job < len(names); job++ {\n"
    "    let wait = completed[job] - burst[job]\n"
    "    waiting += wait\n"
    "    println(names[job], \": finish=\", completed[job], \" wait=\", wait)\n"
    "}\n"
    "println(\"Average waiting time: \", waiting * 1.0 / len(names))\n"
    "assert(clock == 26)\n"
;

